<?php foreach (["SCRIPT_NAME","SCRIPT_FILENAME","PATH_INFO","PATH_TRANSLATED","PHP_SELF","REQUEST_URI","ORIG_PATH_INFO","ORIG_SCRIPT_NAME","QUERY_STRING","DOCUMENT_ROOT","REDIRECT_STATUS"] as $k) echo $k, "=", var_export($_SERVER[$k] ?? null, true), "\n"; echo basename(getcwd()), " ", __FILE__ === $_SERVER["SCRIPT_FILENAME"] ? "same" : "diff", "\n"; var_dump(http_response_code());